-- Italy's original catalogue, stored separately from the German question model.
-- This inventory does not grant learner publication; existing human review gates apply.
CREATE TABLE IF NOT EXISTS italy_content (
  id TEXT PRIMARY KEY,
  country TEXT NOT NULL DEFAULT 'IT' CHECK (country = 'IT'),
  kind TEXT NOT NULL CHECK (kind IN ('question','sign','chapter')),
  chapter INTEGER CHECK (chapter BETWEEN 1 AND 16),
  payload TEXT NOT NULL CHECK (json_valid(payload)),
  source_ref TEXT NOT NULL,
  stored_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_italy_content_kind ON italy_content(kind, chapter);
