INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-001','question',1,'{"id":"it-b-001","chapter":1,"answer":true,"signId":"it-autostrada","prompt":{"ckb":"ئۆتۆسترادا (ڕێگای خێرا) ڕێگایەکە کە سایدەکانی سەربەخۆن یان بە بەربەستێکی نەبڕاو جیاکراونەتەوە و هیچ یەکتربڕێکی هاوتەریبی تێدا نییە.","it":"L''autostrada è una strada a carreggiate indipendenti o separate da spartitraffico invalicabile, priva di intersezioni a raso.","kmrArab":"ئۆتۆسترادا (ڕێکا بلەز) ڕێکەکە کو سایدێن وێ سەربەخۆنە یان ب ئاستەنگەکێ نەبڕی هاتینە جوداکرن و چ یەکتربڕێن هەڤتەریب تێدا نینن.","kmr":"Otostrada rêyeke ku xetên wê serbixwe ne an jî bi astengeke navîn a ku nayê derbasbûn hatine veqetandin, û tu xaçerêyên hemû-astî tê de nînin.","de":"Die Autostrada ist eine Straße mit unabhängigen oder durch einen nicht überfahrbaren Mittelstreifen getrennten Fahrbahnen und ohne niveaugleiche Kreuzungen.","ar":"الأوتوسترادا طريق ذو مسارين مستقلّين أو مفصولين بحاجز وسطي لا يمكن تجاوزه، وبدون تقاطعات على نفس المستوى."},"explanation":{"ckb":"ڕاستە: ئۆتۆسترادا هەمیشە سایدەکانی جیاکراونەتەوە و هیچ چوارڕێیانێکی ئاسایی لەسەر نییە.","it":"VERO: L''autostrada ha sempre carreggiate separate, almeno due corsie per senso di marcia e nessun incrocio a raso.","kmrArab":"ڕاستە: ئۆتۆسترادا هەردەم سایدێن وێ دجوداکرینە و چ چوارڕێیانێن ئاسایی ل سەر نینن.","kmr":"RAST: Otostrada her dem xetên veqetandî, herî kêm du şerîd ji bo her alî, û tu xaçerêyên hemû-astî tune ne.","de":"RICHTIG: Die Autostrada hat immer getrennte Fahrbahnen, mindestens zwei Fahrstreifen je Richtung und keine niveaugleichen Kreuzungen.","ar":"صحيح: الأوتوسترادا لها دائمًا مسارات مفصولة، وحارتان على الأقل لكل اتجاه، ولا توجد تقاطعات على نفس المستوى."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-002','question',1,'{"id":"it-b-002","chapter":1,"answer":false,"signId":"it-autostrada","prompt":{"ckb":"هێڵی فریاگوزاری (تەواری) دەتوانرێت بە شێوەیەکی ئاسایی بەکاربهێنرێت بۆ تێپەڕاندنی ئۆتۆمبێلە هێواشەکان لە کاتی قەرەباڵغیدا.","it":"La corsia di emergenza può essere utilizzata normalmente per il sorpasso dei veicoli lenti in caso di traffico intenso.","kmrArab":"هێلا فریاگوزاریێ (تەواری) دشێت ب شێوەکێ ئاسایی بهێتە بکارئینان بۆ دەربازبوونا ترۆمبێلێن هێدی د دەمێ قەرەبالغیێ دا.","kmr":"Şerîdê acîl (rêya awarte) dikare bi awayekî normal ji bo derbasbûna wesayîtên hêdî di dema trafîka giran de were bikaranîn.","de":"Der Seitenstreifen (Notspur) darf bei dichtem Verkehr normal zum Überholen langsamer Fahrzeuge benutzt werden.","ar":"يمكن استخدام حارة الطوارئ بشكل عادي لتجاوز المركبات البطيئة عند كثافة المرور."},"explanation":{"ckb":"هەڵەیە: هێڵی فریاگوزاری تەنها بۆ وەستانی ناچاری (تێکچوون یان نەخۆشی) و ئۆتۆمبێلی فریاکەوتنە.","it":"FALSO: La corsia di emergenza è riservata esclusivamente alla sosta di emergenza e al transito dei veicoli di soccorso.","kmrArab":"خەلەتە: هێلا فریاگوزاریێ بتنێ بۆ ڕاوەستیانا نەچاری و ترۆمبێلێن فریاکەفتنێ یە.","kmr":"ÇEWT: Şerîdê acîl tenê ji bo rawestana awarte û ji bo derbasbûna wesayîtên gihîştinê ye.","de":"FALSCH: Der Seitenstreifen ist ausschließlich für Nothalte und für die Durchfahrt von Rettungsfahrzeugen bestimmt.","ar":"خطأ: حارة الطوارئ مخصّصة فقط للتوقف الاضطراري ولمرور مركبات الإنقاذ."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-003','question',2,'{"id":"it-b-003","chapter":2,"answer":true,"signId":"it-pericolo","prompt":{"ckb":"هێماکانی مەترسی بە شێوەیەکی گشتی شێوەیان سێگۆشەیە و سەرەکەیان بەرەو سەرەوەیە و بە شێوەی ئاسایی ١٥٠ مەتر پێش خاڵی مەترسی دادەنرێن.","it":"I segnali di pericolo hanno generalmente forma triangolare con il vertice rivolto verso l''alto e sono posti di norma a 150 metri dal punto di pericolo.","kmrArab":"نیشانێن مەترسیێ ب شێوەکێ گشتی شێوێ وان سێگۆشەیە و سەرێ وان بەرەڤ سەری یە و ب شێوێ ئاسایی ١٥٠ مەتران بەری خالا مەترسیێ دهێنە دانان.","kmr":"Nîşaneyên xeterê bi giştî sêgoşe ne û serê wan li jor e, û bi awayekî normal 150 metre berî cihê xeterê têne danîn.","de":"Gefahrzeichen haben in der Regel eine dreieckige Form mit nach oben gerichteter Spitze und stehen normalerweise 150 Meter vor der Gefahrstelle.","ar":"إشارات الخطر مثلّثة الشكل عادةً ورأسها إلى الأعلى، وتوضع عادةً على مسافة ١٥٠ مترًا قبل موقع الخطر."},"explanation":{"ckb":"ڕاستە: دووری ستانداردی ئاگادارکردنەوەی هێماکانی مەترسی ١٥٠ مەترە.","it":"VERO: La distanza standard di preavviso dei segnali di pericolo è di 150 metri.","kmrArab":"ڕاستە: دووراتیا ستاندارد یا ئاگەهدارکرنا نیشانێن مەترسیێ ١٥٠ مەترن.","kmr":"RAST: Mesafeya standard a hişyarkirinê ya nîşaneyên xeterê 150 metre ye.","de":"RICHTIG: Der übliche Vorankündigungsabstand der Gefahrzeichen beträgt 150 Meter.","ar":"صحيح: مسافة التحذير المعتادة لإشارات الخطر هي ١٥٠ مترًا."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-004','question',3,'{"id":"it-b-004","chapter":3,"answer":true,"signId":"it-divieto","prompt":{"ckb":"ئەو هێمایەی لە وێنەکەدایە قەدەغەی دەکات خێرایی لە ٥٠ کم/کاتژمێر زیاتر بێت لەو خاڵەوە کە هێماکەی لێ دانراوە.","it":"Il segnale raffigurato vieta di superare la velocità di 50 km/h a partire dal punto in cui è installato.","kmrArab":"ئەو نیشانا د وێنەی دا قەدەغە دکەت لەزاتی ژ ٥٠ کم/دەمژمێر زێدەتر بیت ژ وێ خالێ یا نیشان لێ هاتیە دانان.","kmr":"Nîşana ku di wêneyê de ye, ji cihê ku hatiye danîn ve lezê ji 50 km/saet zêdetir qedexe dike.","de":"Das abgebildete Zeichen verbietet ab der Stelle, an der es aufgestellt ist, eine Geschwindigkeit über 50 km/h.","ar":"الإشارة المبيّنة تمنع تجاوز سرعة ٥٠ كم/س بدءًا من المكان الذي رُكّبت فيه."},"explanation":{"ckb":"ڕاستە: بەرزترین سنووری خێرایی ڕاستەوخۆ لە دوای هێماکەوە دەست پێدەکات.","it":"VERO: Il limite massimo di velocità entra in vigore immediatamente dopo il segnale.","kmrArab":"ڕاستە: بلندترین سنوورێ لەزاتیێ ئێکسەر پشتی نیشانێ دەست پێدکەت.","kmr":"RAST: Sînorê herî zêde yê lezê yekser piştî nîşanê dest pê dike.","de":"RICHTIG: Die zulässige Höchstgeschwindigkeit gilt unmittelbar ab dem Zeichen.","ar":"صحيح: حدّ السرعة الأقصى يسري مباشرة بعد الإشارة."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-005','question',4,'{"id":"it-b-005","chapter":4,"answer":false,"signId":"it-obbligo","prompt":{"ckb":"ئەو هێمایەی لە وێنەکەدایە ئاماژە بەوە دەکات کە ڕێگەپێدراوە پێچ بکەیتەوە بۆ لای ڕاست بەڵام نابێت ڕاست بڕۆیت.","it":"Il segnale raffigurato indica che è consentito svoltare a destra ma non proseguire diritto.","kmrArab":"ئەو نیشانا د وێنەی دا ئاماژێ ب وێ چەندێ دکەت کو ڕێکپێدایە بزڤڕی بۆ لایێ ڕاستێ بەلێ نابیت ڕاست بچی.","kmr":"Nîşana ku di wêneyê de ye tê wateya ku zivirandina ber bi rastê destûrdar e lê çûna rasterast ne.","de":"Das abgebildete Zeichen bedeutet, dass das Abbiegen nach rechts erlaubt ist, das Geradeausfahren aber nicht.","ar":"الإشارة المبيّنة تعني أن الانعطاف يمينًا مسموح، أما الاستمرار للأمام فغير مسموح."},"explanation":{"ckb":"هەڵەیە: ئەمە هێمای ناچاری ڕۆیشتنە بەرەو پێشەوە (ڕاست)؛ پێچکردنەوە بۆ ڕاست و چەپ قەدەغەیە.","it":"FALSO: È un segnale di direzione obbligatoria diritto; non è consentito svoltare né a destra né a sinistra.","kmrArab":"خەلەتە: ئەڤە نیشانا نەچاریا چوونێ یە بەرەڤ پێشڤە (ڕاست)؛ زڤڕین بۆ ڕاست و چەپێ قەدەغەیە.","kmr":"ÇEWT: Ev nîşana aliyê neçarî yê rasterast e; ne ber bi rastê û ne jî ber bi çepê zivirandin destûrdar e.","de":"FALSCH: Es ist das Zeichen „vorgeschriebene Fahrtrichtung geradeaus“; weder nach rechts noch nach links darf abgebogen werden.","ar":"خطأ: هذه إشارة اتجاه إلزامي للأمام؛ لا يُسمح بالانعطاف يمينًا ولا يسارًا."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-006','question',5,'{"id":"it-b-006","chapter":5,"answer":true,"signId":"it-precedenza","prompt":{"ckb":"لە کاتی بوونی هێمای ''ڕێگا بدە'' پێویستە خێرایی کەم بکەیتەوە و ئەگەر پێویست بوو بوەستیت بۆ ئەوەی ئەو ئۆتۆمبێلانە تێپەڕن کە لەسەر شەقامە یەکتربڕەکەن.","it":"In presenza del segnale ''Dare precedenza'' occorre rallentare e, se necessario, fermarsi per lasciare passare i veicoli che circolano sulla strada che si incrocia.","kmrArab":"د دەمێ هەبوونا نیشانا ''ڕێکێ بدە'' پێدڤیە لەزاتیێ کێم بکەی و ئەگەر پێدڤی بوو ڕاوەستی دا ئەو ترۆمبێلێن ل سەر جاددا یەکتربڕ دەرباز ببن.","kmr":"Li ber nîşana „Mafê pêşiyê bide“ divê mirov lezê kêm bike û heke pêwîst be raweste, da ku wesayîtên li ser rêya xaçerê derbas bibin.","de":"Beim Zeichen „Vorfahrt gewähren“ muss man die Geschwindigkeit verringern und, wenn nötig, anhalten, um den Fahrzeugen auf der kreuzenden Straße die Vorfahrt zu lassen.","ar":"عند إشارة «أعطِ الأولوية» يجب تخفيف السرعة والتوقف إذا لزم الأمر للسماح بمرور المركبات على الطريق المتقاطع."},"explanation":{"ckb":"ڕاستە: پێویستە پێشەنگی بدەیت بەو ئۆتۆمبێلانەی کە لە هەردوو لای ڕاست و چەپەوە دێن.","it":"VERO: Bisogna dare la precedenza ai veicoli provenienti sia da destra che da sinistra.","kmrArab":"ڕاستە: پێدڤیە پێشینەیێ بدەیە وان ترۆمبێلێن ژ هەردوو لایێن ڕاست و چەپێ دهێن.","kmr":"RAST: Divê mafê pêşiyê bê dayîn hem ji wesayîtên ji rastê hem jî ji çepê tên.","de":"RICHTIG: Die Vorfahrt ist den Fahrzeugen sowohl von rechts als auch von links zu gewähren.","ar":"صحيح: يجب إعطاء الأولوية للمركبات القادمة من اليمين ومن اليسار."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-007','question',7,'{"id":"it-b-007","chapter":7,"answer":true,"signId":"it-semaforo","prompt":{"ckb":"کاتێک گڵۆپی ترافیک لایت زەردی جێگیرە، پێویستە پێش هێڵی وەستان بوەستیت، مەگەر هێندە نزیک بیت کە نەتوانیت بە سەلامەتی بوەستیت.","it":"Quando la luce del semaforo è gialla fissa, bisogna fermarsi prima della striscia di arresto, a meno che non ci si trovi così vicino da non poterlo fare in sicurezza.","kmrArab":"دەمێ گڵۆپێ ترافیک لایتێ زەرێ جێگیر بیت، پێدڤیە بەری هێلا ڕاوەستیانێ ڕاوەستی، مەگەر هند نێزیک بی کو نەشێی ب سلامەتی ڕاوەستی.","kmr":"Gava ronahiya lambeya trafîkê zer û sabît be, divê mirov berî xeta rawestanê raweste, ji bilî ku ew qas nêzîk be ku ev bi ewlehî ne pêkan be.","de":"Bei dauerhaft gelbem Licht muss man vor der Haltlinie anhalten, außer man ist ihr schon so nahe, dass dies nicht sicher möglich ist.","ar":"عند الضوء الأصفر الثابت يجب التوقف قبل خط التوقف، إلا إذا كنت قريبًا جدًا بحيث لا يمكن ذلك بأمان."},"explanation":{"ckb":"ڕاستە: لەگەڵ گڵۆپی زەردی جێگیر وەستان ناچارییە ئەگەر بتوانیت بە سەلامەتی بوەستیت.","it":"VERO: Con luce gialla fissa è obbligatorio arrestarsi se è possibile farlo in condizioni di sicurezza.","kmrArab":"ڕاستە: دگەل گڵۆپێ زەرێ جێگیر ڕاوەستیان نەچاری یە ئەگەر بشێی ب سلامەتی ڕاوەستی.","kmr":"RAST: Bi ronahiya zer a sabît de rawestan neçarî ye, heke bi ewlehî pêkan be.","de":"RICHTIG: Bei dauerhaft gelbem Licht ist anzuhalten, wenn es sicher möglich ist.","ar":"صحيح: عند الضوء الأصفر الثابت يجب التوقف إذا كان ذلك ممكنًا بأمان."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-008','question',9,'{"id":"it-b-008","chapter":9,"answer":true,"signId":"it-divieto","prompt":{"ckb":"بەرزترین سنووری خێرایی لە ناو شار و ناوچە نیشتەجێبووەکاندا بە شێوەیەکی گشتی ٥٠ کم/کاتژمێرە، مەگەر هێمایەکی تر دانرابێت.","it":"Il limite massimo di velocità nei centri abitati è generalmente di 50 km/h, salvo diversa segnalazione.","kmrArab":"بلندترین سنوورێ لەزاتیێ د ناڤ باژێڕ و جهێن ئاکنجیبوونێ دا ب شێوەکێ گشتی ٥٠ کم/دەمژمێرە، مەگەر نیشانەکا دی هاتبیتە دانان.","kmr":"Sînorê herî zêde yê lezê li navbera niştecihan bi giştî 50 km/saet e, heke nîşaneke din tune be.","de":"Die Höchstgeschwindigkeit innerhalb geschlossener Ortschaften beträgt in der Regel 50 km/h, sofern nichts anderes ausgeschildert ist.","ar":"الحدّ الأقصى للسرعة داخل المناطق المأهولة هو ٥٠ كم/س عادةً، ما لم تُشر لافتة إلى غير ذلك."},"explanation":{"ckb":"ڕاستە: لە ناو شاردا سنووری گشتی ٥٠ کم/کاتژمێرە.","it":"VERO: Nei centri abitati il limite generale è 50 km/h (elevabile fino a 70 km/h solo su strade urbane di scorrimento con appositi segnali).","kmrArab":"ڕاستە: د ناڤ باژێڕی دا سنوورێ گشتی ٥٠ کم/دەمژمێرە.","kmr":"RAST: Li nav bajêr sînorê giştî 50 km/saet e; tenê li ser rêyên bilez ên bajarî bi nîşanên taybet heta 70 km/saet.","de":"RICHTIG: In geschlossenen Ortschaften gilt allgemein 50 km/h; nur auf städtischen Schnellstraßen mit entsprechendem Zeichen bis 70 km/h.","ar":"صحيح: داخل المدن الحدّ العام ٥٠ كم/س، ويمكن رفعه إلى ٧٠ كم/س فقط على الطرق الحضرية السريعة بإشارات خاصة."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-009','question',11,'{"id":"it-b-009","chapter":11,"answer":true,"signId":"it-stop","prompt":{"ckb":"لە کاتی بوونی هێمای STOP هەمیشە ناچارییە ئۆتۆمبێلەکە لەسەر هێڵی وەستان ڕابگریت، تەنانەت ئەگەر شەقامەکەش چۆڵ دیار بێت.","it":"In presenza del segnale di STOP è sempre obbligatorio arrestare il veicolo in corrispondenza della striscia trasversale di arresto, anche se la strada sembra libera.","kmrArab":"د دەمێ هەبوونا نیشانا STOP هەردەم نەچاری یە ترۆمبێلێ ل سەر هێلا ڕاوەستیانێ ڕابگری، تەنانەت ئەگەر جاددە یا ڤالا ژی دیار بیت.","kmr":"Li ber nîşana STOP her dem neçarî ye ku wesayît li ser xeta rawestanê bê rawestandin, tevî ku rê vala jî xuya bike.","de":"Beim Zeichen STOP muss das Fahrzeug immer an der Haltlinie angehalten werden, auch wenn die Straße frei erscheint.","ar":"عند إشارة STOP يجب دائمًا إيقاف المركبة عند خط التوقف، حتى لو بدا الطريق خاليًا."},"explanation":{"ckb":"ڕاستە: هێمای STOP هەمیشە وەستانی تەواوی ئۆتۆمبێلەکە ناچاری دەکات.","it":"VERO: Lo STOP impone sempre l''arresto completo del veicolo prima di impegnare l''incrocio.","kmrArab":"ڕاستە: نیشانا STOP هەردەم ڕاوەستیانا تەمام یا ترۆمبێلێ نەچاری دکەت.","kmr":"RAST: STOP her dem rawestana tevahî berî ketina xaçerêyê dixwaze.","de":"RICHTIG: STOP verlangt immer das vollständige Anhalten, bevor man in die Kreuzung einfährt.","ar":"صحيح: إشارة STOP تفرض دائمًا التوقف الكامل قبل دخول التقاطع."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-010','question',13,'{"id":"it-b-010","chapter":13,"answer":false,"signId":"it-parcheggio","prompt":{"ckb":"پارککردن (وێستاندنی درێژخایەن) هەمیشە ڕێگەپێدراوە لەسەر پەڕینەوەی پیادە بە مەرجێک ڕێگری لە هاتوچۆ نەکات.","it":"La sosta è sempre consentita in corrispondenza degli attraversamenti pedonali purché non si intralci il traffico.","kmrArab":"پارککرن (ڕاوەستیانا درێژخایەن) هەردەم ڕێکپێدایە ل سەر دەربازبوونا پیادەیان ب مەرجەکێ ئاستەنگیێ بۆ هاتنوچوونێ دروست نەکەت.","kmr":"Park kirin li ser derbasgeha peyaran her dem destûrdar e, bi şertê ku trafîk neyê asteng kirin.","de":"Das Parken auf Fußgängerüberwegen ist immer erlaubt, solange der Verkehr nicht behindert wird.","ar":"الوقوف على معابر المشاة مسموح دائمًا بشرط عدم إعاقة المرور."},"explanation":{"ckb":"هەڵەیە: وەستانی کاتی و پارککردن هەمیشە قەدەغەن لەسەر پەڕینەوەی پیادە و پاسکیل.","it":"FALSO: La fermata e la sosta sono sempre vietate sugli attraversamenti pedonali e ciclabili.","kmrArab":"خەلەتە: ڕاوەستیانا دەمکی و پارککرن هەردەم دقەدەغەنە ل سەر دەربازبوونا پیادە و پاسکیلان.","kmr":"ÇEWT: Rawestan û park kirin li ser derbasgehên peyar û duçerxevanan her dem qedexe ne.","de":"FALSCH: Halten und Parken sind auf Fußgänger- und Radfahrerüberwegen immer verboten.","ar":"خطأ: التوقف والوقوف ممنوعان دائمًا على معابر المشاة والدراجات."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-011','question',15,'{"id":"it-b-011","chapter":15,"answer":true,"signId":"it-autostrada","prompt":{"ckb":"بۆ شۆفێرە نوێیەکان، لە سێ ساڵی یەکەمی وەرگرتنی مۆڵەتی B دا، ڕێگەپێدراو نییە خێرایی لە ١٠٠ کم/کاتژمێر زیاتر بێت لە ئۆتۆسترادا.","it":"Per i neopatentati, nei primi tre anni dal conseguimento della patente B, non è consentito superare la velocità di 100 km/h in autostrada.","kmrArab":"بۆ شۆفێرێن نوی، د سێ سالێن ئێکێ یێن وەرگرتنا دەستوورا B دا، ڕێکپێدای نینە لەزاتی ژ ١٠٠ کم/دەمژمێر زێدەتر بیت ل ئۆتۆسترادا.","kmr":"Ji bo ajokarên nû, di sê salên pêşîn ên piştî bidestxistina destûrnameya B de, li otostrada lez ji 100 km/saet zêdetir destûrdar nîne.","de":"Für Fahranfänger gilt in den ersten drei Jahren nach Erwerb der Fahrerlaubnis B auf der Autostrada eine Höchstgeschwindigkeit von 100 km/h.","ar":"بالنسبة للحاصلين الجدد على الرخصة، في السنوات الثلاث الأولى بعد الحصول على رخصة B، لا يجوز تجاوز ١٠٠ كم/س على الأوتوسترادا."},"explanation":{"ckb":"ڕاستە: لە ٣ ساڵی یەکەمدا بەرزترین خێرایی ١٠٠ کم/کاتژمێرە لە ئۆتۆسترادا.","it":"VERO: Nei primi 3 anni dal rilascio della patente B il limite massimo è 100 km/h in autostrada e 90 km/h sulle extraurbane principali.","kmrArab":"ڕاستە: د ٣ سالێن ئێکێ دا بلندترین لەزاتی ١٠٠ کم/دەمژمێرە ل ئۆتۆسترادا.","kmr":"RAST: Di 3 salên pêşîn de li otostrada herî zêde 100 km/saet û li ser rêyên sereke yên derveyî bajêr 90 km/saet e.","de":"RICHTIG: In den ersten 3 Jahren gilt auf der Autostrada höchstens 100 km/h und auf den Hauptstraßen außerhalb geschlossener Ortschaften 90 km/h.","ar":"صحيح: في السنوات الثلاث الأولى الحدّ الأقصى ١٠٠ كم/س على الأوتوسترادا و٩٠ كم/س على الطرق الرئيسية خارج المدن."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
INSERT INTO italy_content (id,kind,chapter,payload,source_ref) VALUES ('it-b-012','question',16,'{"id":"it-b-012","chapter":16,"answer":true,"signId":"it-pericolo","prompt":{"ckb":"لە کاتی ڕووداوی هاتوچۆدا کە برینداری تێدا بێت، ناچارییە بوەستیت، مەترسییەکە بە سێگۆشەی ئاگادارکەرەوە دیاری بکەیت و فریاگوزاری پێویست پێشکەش بکەیت.","it":"In caso di incidente stradale con feriti, è obbligatorio fermarsi, segnalare il pericolo con il triangolo mobile e prestare l''assistenza possibile.","kmrArab":"د دەمێ ڕوودانا هاتنوچوونێ دا کو بریندار تێدا بن، نەچاری یە ڕاوەستی، مەترسیێ ب سێگۆشا ئاگەهدارکرنێ دیار بکەی و هاریکاریا پێدڤی پێشکێش بکەی.","kmr":"Di qezayeke trafîkê ya bi birîndaran de neçarî ye ku mirov raweste, xeterê bi sêgoşeya hişyariyê nîşan bide û alîkariya pêkan pêşkêş bike.","de":"Bei einem Verkehrsunfall mit Verletzten ist man verpflichtet anzuhalten, die Gefahrenstelle mit dem Warndreieck zu sichern und die mögliche Hilfe zu leisten.","ar":"في حال وقوع حادث مروري مع وجود جرحى، يجب التوقف وتأمين موقع الخطر بالمثلث العاكس وتقديم المساعدة الممكنة."},"explanation":{"ckb":"ڕاستە: بەجێهێشتنی بریندار و پێشکەشنەکردنی فریاگوزاری تاوانێکی یاسایی قورسە.","it":"VERO: Omettere il soccorso in caso di incidente con feriti costituisce un grave reato penale.","kmrArab":"ڕاستە: هێلانا برینداری و پێشکێشنەکرنا فریاگوزاریێ تاوانەکا یاسایی یا گرانە.","kmr":"RAST: Nedayîna alîkariyê di qezayeke bi birîndaran de sûcekî cezayî yê giran e.","de":"RICHTIG: Unterlassene Hilfeleistung bei einem Unfall mit Verletzten ist eine schwere Straftat.","ar":"صحيح: الامتناع عن تقديم المساعدة في حادث فيه جرحى يُعدّ جريمة جنائية خطيرة."},"questionCode":null,"licenseClasses":["B"],"sourceType":"original","contentVersion":"2026.11-it-original-1","reviewStatus":"pending","publicationStatus":"published"}','src/content/italy/questions.ts') ON CONFLICT(id) DO NOTHING;
